'use client';
import Link from 'next/link';import {useUiI18n} from '@/lib/i18n/provider';import type {HistoryPage} from '@/lib/knowledge-admin/types';import type {HistoryPage as LegacyHistoryPage} from '@/lib/study/types';
const labels={started:'study.event.started',completed:'study.event.completed','review-started':'study.event.reviewStarted','review-finished':'study.event.reviewFinished','note-saved':'study.event.noteSaved','note-deleted':'study.event.noteDeleted'} as const;
export function ManagedHistory({page,legacy,filters={}}:{page:HistoryPage;legacy?:LegacyHistoryPage;filters?:Record<string,string>}){const{t,locale}=useUiI18n();const items=[...page.items.map(e=>({id:e.id,at:e.recordedAt,kind:e.kind,knowledge:e.knowledge.id,topics:e.topicKeys.join(' · '),legacy:false})),...(legacy?.items??[]).map(e=>({id:e.id,at:e.occurredAt,kind:e.kind,knowledge:e.knowledge.id,topics:'',legacy:true}))].sort((a,b)=>b.at.localeCompare(a.at));return <section className="panel"><h1>{t('managed.history',{})}</h1><p>{t('managed.historyTruth',{})}</p><form><label>{t('managed.id',{})}<input name="knowledgeId" defaultValue={filters.knowledgeId}/></label><label>{t('managed.topics',{})}<input name="topicKey" defaultValue={filters.topicKey}/></label><button className="button">{t('managed.search',{})}</button></form><ol>{items.map(e=><li key={(e.legacy?'legacy:':'managed:')+e.id}><time dateTime={e.at}>{new Date(e.at).toLocaleString(locale)}</time> · {t(labels[e.kind],{})} · {e.legacy?<span>{e.knowledge} · {t('managed.legacyHistory',{})}</span>:<Link prefetch={false} href={`/knowledge/${e.knowledge}`}>{e.knowledge}</Link>} · {e.topics}</li>)}</ol>{items.length===0&&<p>{t('managed.empty',{})}</p>}{page.nextCursor&&<Link prefetch={false} href={'/learning-history?'+new URLSearchParams({...filters,cursor:page.nextCursor})}>{t('managed.next',{})}</Link>}{legacy?.nextCursor&&<Link prefetch={false} href={'/learning-history?'+new URLSearchParams({...filters,legacyCursor:legacy.nextCursor})}>{t('managed.legacyHistory',{})} · {t('managed.next',{})}</Link>}</section>}
